    logo: 'Logo Design (500x500)',
    presentation: 'Presentation (1920x1080)',
    infographic: 'Infographic (800x2000)',
    youtube_thumbnail: 'YouTube Thumbnail (1280x720)',
    business_card: 'Business Card (3.5x2)',
